#!/usr/bin/env bash
# Generates the TypeScript and Kotlin protocol types from crates/protocol.
#
#   scripts/gen-types.sh          regenerate the committed files
#   scripts/gen-types.sh --check  fail if the committed files are out of date (CI)
#
# The protocol is modified ONLY in crates/protocol, then this script is run.
set -euo pipefail

# Must match the "Generated by typeshare X" header of the committed files.
TYPESHARE_VERSION="1.13.4"

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
PROTOCOL_DIR="$ROOT/crates/protocol"
CONFIG="$ROOT/typeshare.toml"
TS_OUT="$ROOT/apps/desktop/src/generated/protocol.ts"
KT_OUT="$ROOT/apps/android/app/src/main/java/io/github/hugoambiehl/padboard/protocol/Protocol.kt"

CHECK=false
case "${1:-}" in
  "") ;;
  --check) CHECK=true ;;
  *) echo "usage: $0 [--check]" >&2; exit 2 ;;
esac

if ! command -v typeshare >/dev/null 2>&1; then
  echo "error: typeshare not found. Install it with:" >&2
  echo "  cargo install typeshare-cli --version $TYPESHARE_VERSION --locked" >&2
  exit 1
fi
installed="$(typeshare --version | awk '{print $2}')"
if [[ "$installed" != "$TYPESHARE_VERSION" ]]; then
  echo "error: typeshare $installed found, $TYPESHARE_VERSION expected. Install it with:" >&2
  echo "  cargo install typeshare-cli --version $TYPESHARE_VERSION --locked --force" >&2
  exit 1
fi

# generate <lang> <output file>
generate() {
  mkdir -p "$(dirname "$2")"
  RUST_LOG=error typeshare "$PROTOCOL_DIR" --config-file="$CONFIG" --lang="$1" --output-file="$2" >/dev/null
}

if $CHECK; then
  tmp="$(mktemp -d)"
  trap 'rm -rf "$tmp"' EXIT
  generate typescript "$tmp/protocol.ts"
  generate kotlin "$tmp/Protocol.kt"
  status=0
  for pair in "$tmp/protocol.ts|$TS_OUT" "$tmp/Protocol.kt|$KT_OUT"; do
    fresh="${pair%%|*}"
    committed="${pair#*|}"
    if ! diff -u --label "${committed#"$ROOT"/} (committed)" --label "(regenerated)" \
        "$committed" "$fresh"; then
      status=1
    fi
  done
  if [[ $status -ne 0 ]]; then
    echo "error: generated protocol types are out of date. Run scripts/gen-types.sh and commit." >&2
    exit 1
  fi
  echo "Generated protocol types are up to date."
else
  generate typescript "$TS_OUT"
  generate kotlin "$KT_OUT"
  echo "Generated:"
  echo "  ${TS_OUT#"$ROOT"/}"
  echo "  ${KT_OUT#"$ROOT"/}"
fi
